const path = require("node:path");
const {
  createContractProgram,
  renderTypeAliases,
  writeOrCheckContract,
  checkContractDeclarations,
} = require("./contract-generation.cjs");

const source = path.resolve(__dirname, "../src/lib/customer-purchases/contracts.ts");
const target = path.resolve(__dirname, "../.mercur/customer-contracts.d.ts");
const program = createContractProgram([source], { skipLibCheck: false });
const result =
  "// Generated by scripts/generate-customer-contracts.cjs. Do not edit.\n" +
  renderTypeAliases(program, [source]) +
  "\n";

if (
  writeOrCheckContract(
    target,
    result,
    "Customer contracts are stale; run pnpm customers:contracts:generate",
  )
) {
  checkContractDeclarations(
    [target],
    "Customer contract declaration failed typechecking",
  );
}
